/* ---------- Pins ---------- */
#define DHT_PIN     4
#define DHT_TYPE    DHT11
#define RELAY1_PIN  5
#define RELAY2_PIN  6

/* Most 2-channel relay modules are ACTIVE LOW */
#define RELAY_ACTIVE_LOW true

DHT dht(DHT_PIN, DHT_TYPE);
WebSocketMCP mcpClient;

/* ---------- Relay helpers ---------- */
void setRelay(uint8_t pin, bool on) {
  if (RELAY_ACTIVE_LOW) {
    digitalWrite(pin, on ? LOW : HIGH);
  } else {
    digitalWrite(pin, on ? HIGH : LOW);
  }
}

bool relayIsOn(uint8_t pin) {
  int state = digitalRead(pin);
  return RELAY_ACTIVE_LOW ? (state == LOW) : (state == HIGH);
}

/* ---------- MCP tools ---------- */
void setupMCPTools() {

  mcpClient.addTool(
    "self.relay1.set", "Turn relay 1 on or off.", R"({"type":"object","properties":{"on":{"type":"boolean"}},"required":["on"]})", [](const String& args) -> String {
      bool on = args.indexOf("\"on\":true") >= 0;
      setRelay(RELAY1_PIN, on);
      return on ? "Relay 1 is ON" : "Relay 1 is OFF";
    }
  );

  mcpClient.addTool(
    "self.relay2.set", "Turn relay 2 on or off.", R"({"type":"object","properties":{"on":{"type":"boolean"}},"required":["on"]})", [](const String& args) -> String {
      bool on = args.indexOf("\"on\":true") >= 0;
      setRelay(RELAY2_PIN, on);
      return on ? "Relay 2 is ON" : "Relay 2 is OFF";
    }
  );

  mcpClient.addTool(
    "self.relays.all_off", "Turn both relays off.", R"({"type":"object","properties":{}})", [](const String& args) -> String {
      setRelay(RELAY1_PIN, false);
      setRelay(RELAY2_PIN, false);
      return "Both relays are OFF";
    }
  );

  mcpClient.addTool(
    "self.relays.status", "Get the current status of relay 1 and relay 2.", R"({"type":"object","properties":{}})", [](const String& args) -> String {
      String result = "{";
      result += "\"relay1\":";
      result += relayIsOn(RELAY1_PIN) ? "true" : "false";
      result += ",\"relay2\":";
      result += relayIsOn(RELAY2_PIN) ? "true" : "false";
      result += "}";
      return result;
    }
  );

  mcpClient.addTool(
    "self.dht11.read", "Read temperature in Celsius and relative humidity from the DHT11 sensor.", R"({"type":"object","properties":{}})", [](const String& args) -> String {
      float humidity = dht.readHumidity();
      float temperature = dht.readTemperature();

      if (isnan(humidity) || isnan(temperature)) {
        return "{\"error\":\"DHT11 read failed\"}";
      }

      String result = "{";
      result += "\"temperature_c\":";
      result += String(temperature, 1);
      result += ",\"humidity_percent\":";
      result += String(humidity, 1);
      result += "}";
      return result;
    }
  );
}

/* ---------- Setup ---------- */
void setup() {
  Serial.begin(115200);
  delay(500);

  pinMode(RELAY1_PIN, OUTPUT);
  pinMode(RELAY2_PIN, OUTPUT);

  setRelay(RELAY1_PIN, false);
  setRelay(RELAY2_PIN, false);

  dht.begin();

  Serial.println();
  Serial.println("=== XiaoZhi MCP IoT Node ===");

  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASS);

  Serial.print("Connecting to Wi-Fi");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }

  Serial.println();
  Serial.print("Wi-Fi connected. IP: ");
  Serial.println(WiFi.localIP());

  setupMCPTools();

  mcpClient.begin(MCP_ENDPOINT);

  Serial.println("MCP connection started.");
}

/* ---------- Loop ---------- */
void loop() {
  mcpClient.loop();

  if (WiFi.status() != WL_CONNECTED) {
    WiFi.reconnect();
  }

  delay(10);
}
